import importlib
import io
import os
import sys

toolsDirectory = os.path.dirname(os.path.abspath(__file__))
if toolsDirectory not in sys.path:
    sys.path.insert(0, toolsDirectory)
definitionsDirectory = os.path.normpath(os.path.join(toolsDirectory, '..', '..', 'definitions'))
if definitionsDirectory not in sys.path:
    sys.path.insert(0, definitionsDirectory)

import generatorPaths as paths                                                          # noqa: E402
import enumEmitter                                                                      # noqa: E402
import outputVariableEmitter                                                            # noqa: E402
from autoGenerateHelper import PyLatexRST, GetDateStr, WriteTextIfDifferent             # noqa: E402
from autoGenerateHelper import MarkdownLabel                                            # noqa: E402
from tex2md import NormalizeHeadings                                                    # noqa: E402
from autoGenerateHelper import localListFunctionNames, localListClassNames, localListEnumNames  # noqa: E402
from pybindTypes import declarationCalls                                                # noqa: E402


class Replay:
    """replays recorded declaration calls into a PyLatexRST; keeps the stub sections"""
    def __init__(self):
        self.stubSections = ''  #closed stub sections, latest first
        self.savedCpp = None
        self.savedStub = None

    def __call__(self, calls, plr):
        for name, args, kwargs in calls:
            if name in declarationCalls:
                getattr(plr, name)(*args, **kwargs)
            elif name == 'CppCode':
                plr.sPy += args[0]
            elif name == 'LatexCode':
                plr.sLatex += args[0]
            elif name == 'StubCode':
                plr.sPyi += args[0]
            elif name == 'ResetRST':
                plr.sRST = ''
                plr.sMarkdown = ''   #the chapter title lives in the index (revision2026 R7.1.6)
            elif name == 'BeginCppWrittenByHand':
                assert self.savedCpp is None, 'BeginCppWrittenByHand is not closed'
                self.savedCpp = plr.sPy
            elif name == 'EndCppWrittenByHand':
                plr.sPy = self.savedCpp
                self.savedCpp = None
            elif name == 'BeginNoStub':
                assert self.savedStub is None, 'BeginNoStub is not closed'
                self.savedStub = plr.sPyi
            elif name == 'EndNoStub':
                plr.sPyi = self.savedStub
                self.savedStub = None
            elif name == 'EndStubSection':
                self.stubSections = plr.sPyi + self.stubSections
                plr.sPyi = ''
            elif name == 'CppFinishClass':
                plrFinish = PyLatexRST()
                plrFinish.DefPyFinishClass(args[0])
                plr.sPy += plrFinish.PyStr()
            elif name == 'ExtensionRST':
                with open(paths.generatedDir+args[0]+'.rst', 'r', encoding='utf8') as f:
                    plr.sRST += f.read()
                with open(paths.generatedDir+args[0]+'.md', 'r', encoding='utf8') as f:
                    plr.sMarkdown += '\n' + f.read()
            else:
                raise ValueError('unknown declaration call ' + name)
        assert self.savedCpp is None and self.savedStub is None, 'unbalanced Begin/End declaration calls'


#the file names are those of the RST split (CreateNewRSTfile); a page needs a title of its own,
#because the LaTeX sections inside it start one level below the chapter
markdownPageTitles = {
    'GeneralInformation': 'General information',
    'Exudyn': 'Exudyn module',
    'SystemContainer': 'SystemContainer',
    'Renderer': 'Renderer',
    'MainSystem': 'MainSystem',
    'SystemData': 'SystemData',
    'Symbolic': 'Symbolic',
    'GeneralContact': 'GeneralContact',
    'DataStructures': 'Data structures',
    'TypeDefinitions': 'Type definitions',
    }


def WriteMarkdownPages(plr):
    """docs/generated/cInterface/: one page per file of the RST split, plus the chapter index
    which carries the chapter label (revision2026 step R7.1.6)"""
    markdownDir = os.path.join(paths.repositoryRoot, 'docs', 'generated', 'cInterface')
    os.makedirs(markdownDir, exist_ok=True)

    def Banner(title):
        return ('<!-- GENERATED by tools/generators/pybindEmitter.py from definitions/ '
                '- do not edit -->\n'
                '# ' + title + '\n\n')

    indexText = ('<!-- GENERATED by tools/generators/pybindEmitter.py from definitions/ '
                 '- do not edit -->\n'
                 + MarkdownLabel('sec:pcpp:command:interface') + '\n'
                 '# Python-C++ command interface\n\n'
                 '```{toctree}\n:maxdepth: 3\n\n')

    written = 0
    for (name, text) in plr.markdownFileLists:
        if text.strip() == '':
            continue
        page = NormalizeHeadings(Banner(markdownPageTitles.get(name, name))
                                 + text.strip()) + '\n'
        with io.open(os.path.join(markdownDir, name + '.md'), 'w', encoding='utf8',
                     newline='\n') as file:
            file.write(page)
        written += 1
        indexText += name + '\n'

    with io.open(os.path.join(markdownDir, 'cInterfaceIndex.md'), 'w', encoding='utf8',
                 newline='\n') as file:
        file.write(indexText + '```\n')

    print('pybindEmitter: ' + str(written + 1) + ' Markdown file(s) written')


def Declarations(name):
    return importlib.import_module(name)


def main():
    localListFunctionNames.clear()
    localListClassNames.clear()
    localListEnumNames.clear()
    replay = Replay()

    #the chapter introduction; it goes before everything else, but the enums are replayed first
    plrmain = PyLatexRST('','', '')
    replay(Declarations('pybindGeneralInformation').pb.calls, plrmain)

    #the OutputVariableType registrator owns the enum and writes its C++ header; enumEmitter writes EnumTypes.h
    outputVariableEmitter.EmitHeader()
    enumEmitter.EmitHeader()

    plr = PyLatexRST('','', '')
    replay(Declarations('pybindEnums').pb.calls, plr)
    sStubEnums = plr.sPyi
    plr.sPyi = ''
    sLenum = plr.sLatex #the latex enum string is used later on!
    sRSTenum = plr.sRST #the latex enum string is used later on!
    sMarkdownEnum = plr.sMarkdown #same for Markdown (revision2026 step R7.1.6)

    #now start the main file:
    plr.sRST = ''
    plr.sLatex = ''
    plr.sMarkdown = ''
    plr.CreateNewRSTfile('GeneralInformation')
    plr.sLatex = plrmain.sLatex
    plr.sRST = plrmain.sRST
    plr.sMarkdown = plrmain.sMarkdown

    for name in ['pybindModule', 'pybindSystemContainer', 'pybindRenderer', 'pybindMainSystem', 'pybindSystemData']:
        replay(Declarations(name).pb.calls, plr)

    #the symbolic submodule: its stubs go into a separate file, its documentation into plr
    symbolic = Declarations('pybindSymbolic')
    replay(symbolic.pb.calls, plr)
    plrsym = PyLatexRST('','', '')
    replay(symbolic.symbolicModule.calls, plrsym)
    plrsym.sPyi = plrsym.sPyi.replace('symbolic.','')
    plr.sRST += plrsym.sRST
    plr.sLatex += plrsym.sLatex
    plr.sMarkdown += plrsym.sMarkdown

    for name in ['pybindGeneralContact', 'pybindDataStructures']:
        replay(Declarations(name).pb.calls, plr)
    sStubEnums += plr.sPyi #the type definitions are needed earlier and go into enums file
    savedPyi = replay.stubSections

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #now finalize files:
    plr.CreateNewRSTfile('TypeDefinitions')
    plr.sLatex += sLenum #put latex description of enums after the systemData section
    plr.sRST += sRSTenum #put RST description of enums after the systemData section
    plr.sMarkdown += sMarkdownEnum
    plr.CreateNewRSTfile('') #this finalizes the list

    directoryString = paths.autogeneratedDir
    pybindFile = directoryString + 'pybind_manual_classes.h'

    #write only if content changed, ignoring the volatile 'last modified' date line;
    #otherwise the file shows up as modified on every run and hides real generator drift
    sPybind = ''
    sPybind += '// AUTO:  ++++++++++++++++++++++\n'
    sPybind += '// AUTO:  pybind11 manual module includes; generated by Johannes Gerstmayr\n'
    sPybind += '// AUTO:  last modified = '+ GetDateStr() + '\n'
    sPybind += '// AUTO:  ++++++++++++++++++++++\n'
    sPybind += plr.PyStr()
    WriteTextIfDifferent(pybindFile, sPybind, True)

    #docs/theDoc/manual_interfaces.tex and docs/RST/cInterface/ are not written since
    #revision2026 step R7.1.6; the LaTeX and RST strings are still built, and die in R7.1.7

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #MARKDOWN, revision2026 step R7.1.6: the same pages, in docs/generated/ where emitter output
    #belongs (decision D10). docs/theDoc/manual_interfaces.tex and docs/RST/cInterface/ go away
    #with this step; the LaTeX and RST branches above go in R7.1.7.
    WriteMarkdownPages(plr)

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #stub file .pyi (will be merged with general file)
    file=io.open(paths.generatedDir+'stubAutoBindings.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(savedPyi)
    #file.write(plr.sPyi)
    file.close()

    #stub file symbolic.pyi (will be merged with general file)
    file=io.open(paths.generatedDir+'stubSymbolic.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(plrsym.sPyi)
    #file.write(plr.sPyi)
    file.close()

    file=io.open(paths.generatedDir+'stubEnums.pyi','w',encoding='utf8')  #clear file by one write access
    file.write(sStubEnums)
    file.close()

    #%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    #write function, class, ... names for conf.py
    exuDir = paths.rstDir

    sConfHelper = ''
    sConfHelper += '#this is a helper file to define additional keywords for examples\n'
    sConfHelper += '#Created: 2023-03-17, Johannes Gerstmayr\n\n'

    #some manual entries ...
    localListClassNames.append('SimulationSettings')
    localListFunctionNames.append('visualizationSettings') #in fact, it is a member
    localListFunctionNames.append('systemData') #in fact, it is a member
    localListFunctionNames.append('systemIsConsistent') #in fact, it is a member
    localListFunctionNames.append('interactiveMode') #in fact, it is a member

    #list of classes and enum classes:
    sConfHelper += 'listClassNames=['
    for s in localListClassNames:
        sConfHelper += "'" + s + "'" + ', '
    for s in localListEnumNames:
        sConfHelper += "'" + s + "'" + ', '
    sConfHelper += ']\n\n'

    sConfHelper += 'listFunctionNames=['
    for s in localListFunctionNames:
        sConfHelper += "'" + s + "'" + ', '
    sConfHelper += ']\n\n'


    with open(exuDir+'confHelper.py', 'w', encoding='utf8') as f:
        f.write(sConfHelper)



    return 0


if __name__ == '__main__':
    sys.exit(main())
